import{_ as e,o as a,c as i,ag as o}from"./chunks/framework.NIGIbcGl.js";const u=JSON.parse('{"title":"Mitra Registration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"customer/mitra-registration/index.md","filePath":"customer/mitra-registration/index.md"}'),s={name:"customer/mitra-registration/index.md"};function n(r,t,d,l,p,c){return a(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="mitra-registration-guide" tabindex="-1">Mitra Registration Guide <a class="header-anchor" href="#mitra-registration-guide" aria-label="Permalink to &quot;Mitra Registration Guide&quot;">​</a></h1><p>Self-serve onboarding for <strong>Mitra</strong> (partner) applicants. A mitra submits one form — the registration details and the signed MoU together, in a single request — and, once an admin approves, is issued a per-tier registration number (<code>MS.</code> / <code>MG.</code>) and the pricing access for their tier.</p><blockquote><p><strong>Mitra vs B2B vs Partner.</strong> Mitra is a <strong>customer-onboarding</strong> flow, distinct from the admin-provisioned banking <strong>Partner</strong> API-key module and from the <strong>B2B</strong> KYC flow (which requires NIB/NPWP). Individuals with no company documents can register as mitra.</p></blockquote><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Prefix</th><th>On approval</th></tr></thead><tbody><tr><td>Mitra Silver</td><td><code>MS.</code></td><td>Promo pricing access</td></tr><tr><td>Mitra Gold</td><td><code>MG.</code></td><td>Promo + special-B2B pricing access</td></tr></tbody></table><p><strong>Who can apply:</strong> anyone. You do <strong>not</strong> need an organization.</p><h2 id="the-organization-form-is-optional" tabindex="-1">The organization form is optional <a class="header-anchor" href="#the-organization-form-is-optional" aria-label="Permalink to &quot;The organization form is optional&quot;">​</a></h2><p><code>companyName</code> (with the optional <code>companyAddress</code>) <strong>is</strong> the organization form, and it decides what approval creates:</p><table tabindex="0"><thead><tr><th>You supply <code>companyName</code></th><th>On approval you get</th></tr></thead><tbody><tr><td><strong>Yes</strong></td><td>An <strong>Organization</strong> + a SAR organization wallet, and your account is promoted to a <code>B2B</code> member of it. The tier flags live on the organization.</td></tr><tr><td><strong>No</strong> (blank / omitted)</td><td><strong>No organization.</strong> You are an <strong>individual partner</strong>: your account stays <code>B2C</code> and the tier + promo flags are set on <strong>you</strong>. Pricing is identical — a Gold individual partner gets the same special pricing a Gold organization gets.</td></tr></tbody></table><p>Blank and whitespace-only values count as <strong>not supplied</strong> — an empty text input is the same as omitting the field.</p><p>Two rules follow from this:</p><ul><li><strong><code>applicantType: COMPANY</code> requires <code>companyName</code>.</strong> Declaring yourself a company and then not naming one is rejected with <code>400</code>.</li><li><code>applicantType: INDIVIDUAL</code> <strong>may</strong> still supply a <code>companyName</code> (a sole proprietor who wants an organization). The two fields are independent: <code>applicantType</code> decides whether a <strong>KTP</strong> is required; <code>companyName</code> decides whether an <strong>Organization</strong> is created.</li></ul><table tabindex="0"><thead><tr><th><code>applicantType</code></th><th>organization form</th><th>KTP required</th><th>Organization created</th></tr></thead><tbody><tr><td><code>INDIVIDUAL</code></td><td>blank</td><td>yes</td><td><strong>no</strong> — individual partner</td></tr><tr><td><code>INDIVIDUAL</code></td><td>filled</td><td>yes</td><td>yes (sole proprietor)</td></tr><tr><td><code>COMPANY</code></td><td>blank</td><td>no</td><td><strong>400 — rejected</strong></td></tr><tr><td><code>COMPANY</code></td><td>filled</td><td>no</td><td>yes</td></tr></tbody></table><hr><h2 id="required-documents" tabindex="-1">Required Documents <a class="header-anchor" href="#required-documents" aria-label="Permalink to &quot;Required Documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Required for</th><th>Accepted types</th></tr></thead><tbody><tr><td>SPK</td><td>All applicants</td><td>PDF, DOC, DOCX</td></tr><tr><td>KTP</td><td><code>INDIVIDUAL</code> only</td><td>JPEG, PNG, WebP, PDF</td></tr><tr><td>Partnership file</td><td>All applicants</td><td>PDF, DOC, DOCX, JPEG, PNG, WebP</td></tr><tr><td>Payment proof</td><td>All applicants — <code>SILVER</code> (100 SAR), <code>GOLD</code> (50,000 SAR)</td><td>PDF, JPEG, PNG, WebP</td></tr></tbody></table><p>Max upload size: <strong>10 MB per file</strong>, and <strong>25 MB for all documents together</strong> in one registration request.</p><p><strong>The signed MoU (<code>spk</code>) must be attached to the registration itself</strong> — it is sent in the same request as the form fields, and a submission without it is rejected. The other three documents are optional at submit time and can be added afterwards, once you are signed in (see <a href="#2-add-or-replace-a-document-after-signing-in">§2</a>). That is deliberate: you usually will not have a payment proof until you have the bank details.</p><p>Approval still requires the full set — SPK, partnership file and payment proof (plus KTP for <code>INDIVIDUAL</code>). Submitting with only the SPK is fine; being <em>approved</em> with only the SPK is not.</p><blockquote><p>The <strong>Gold 50,000 SAR deposit</strong> proof <strong>is</strong> captured here (uploaded as the payment proof). The deposit transfer itself is verified manually by an admin off-system and is <strong>not</strong> credited to your wallet balance.</p></blockquote><hr><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><h3 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;host&gt;/api/v1</span></span></code></pre></div><h3 id="_1-submit-a-registration-documents-included" tabindex="-1">1. Submit a registration (documents included) <a class="header-anchor" href="#_1-submit-a-registration-documents-included" aria-label="Permalink to &quot;1. Submit a registration (documents included)&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register</code></p><p><strong>Content-Type:</strong> <code>multipart/form-data</code> — the form fields and the documents travel in <strong>one</strong> request. There is no separate upload step for the first submission.</p><p><strong>Authentication:</strong> Optional. Unauthenticated submissions resolve or create a passwordless account from the <strong><code>applicantEmail</code></strong> — that address <strong>is</strong> your login identity.</p><blockquote><p>⚠️ <strong>Sign in with the email you registered with.</strong> Your account is never matched or created from <code>applicantPhone</code>; the phone is contact data, not a credential. If you already have a customer account under a <em>different</em> email (e.g. a personal one) and you register with your <strong>company</strong> email, you now have two separate accounts — and only the company one holds the application.</p></blockquote><p><strong>Form fields:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>tier</code></td><td>yes</td><td><code>SILVER</code> or <code>GOLD</code></td></tr><tr><td><code>applicantType</code></td><td>yes</td><td><code>COMPANY</code> or <code>INDIVIDUAL</code></td></tr><tr><td><code>applicantName</code></td><td>yes</td><td></td></tr><tr><td><code>applicantEmail</code></td><td>yes</td><td>your login identity</td></tr><tr><td><code>applicantPhone</code></td><td>yes</td><td>contact data only</td></tr><tr><td><code>companyName</code></td><td>if <code>COMPANY</code></td><td>the <strong>organization form</strong> — see above. Omit to register as an individual partner with no organization.</td></tr><tr><td><code>companyAddress</code></td><td>no</td><td></td></tr><tr><td><code>spkNumber</code></td><td>no</td><td>when supplied, must match <code>05.XXX/ADI/MM/YYYY</code></td></tr></tbody></table><p><strong>File parts:</strong></p><table tabindex="0"><thead><tr><th>Part</th><th>Required</th><th>Accepted types</th></tr></thead><tbody><tr><td><code>spk</code></td><td><strong>yes</strong></td><td>PDF, DOC, DOCX</td></tr><tr><td><code>ktp</code></td><td>no</td><td>JPEG, PNG, WebP, PDF</td></tr><tr><td><code>partnership</code></td><td>no</td><td>PDF, DOC, DOCX, JPEG, PNG, WebP</td></tr><tr><td><code>payment-proof</code></td><td>no</td><td>PDF, JPEG, PNG, WebP</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/mitra/register&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tier=SILVER&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantType=COMPANY&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantName=Budi Santoso&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantEmail=budi@example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantPhone=+6281234567890&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;companyName=PT Mitra Sejahtera&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;companyAddress=Jl. Merdeka No. 1, Jakarta&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;spkNumber=05.123/ADI/07/2026&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;spk=@SPK.pdf&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;partnership=@partnership.pdf&quot;</span></span></code></pre></div><p>Individual partner, SPK only — the minimum valid submission:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/mitra/register&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;tier=GOLD&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantType=INDIVIDUAL&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantName=Siti Aminah&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantEmail=siti@example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;applicantPhone=+6281234567891&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;spk=@SPK.pdf&quot;</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the created registration (<code>status: &quot;PENDING&quot;</code>) with every attached document already linked, in the <a href="#what-the-registration-object-contains">customer shape</a>.</p><blockquote><p>If you send an <code>spkNumber</code>, the SPK&#39;s display filename is set to the number-derived name (e.g. <code>05.123_ADI_07_2026.pdf</code>) in the very same response.</p></blockquote><p><strong>Errors:</strong></p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><code>400</code></td><td>No <code>spk</code> part — the signed MoU is required.</td></tr><tr><td><code>400</code></td><td>A file has a disallowed type for its slot, or is not really the type it claims (the content is checked, not just the extension).</td></tr><tr><td><code>400</code></td><td><code>applicantType: &quot;COMPANY&quot;</code> with no <code>companyName</code>.</td></tr><tr><td><code>400</code></td><td>The documents together exceed <strong>25 MB</strong>.</td></tr><tr><td><code>413</code></td><td>A single file exceeds <strong>10 MB</strong>.</td></tr><tr><td><code>409</code></td><td>An open registration already exists for this applicant, <strong>or</strong> the account already has an <strong>approved</strong> registration (one approved registration per account, ever).</td></tr><tr><td><code>409</code></td><td>The email belongs to an existing B2B or admin account — sign in and manage that organization instead.</td></tr></tbody></table><blockquote><p>If a document fails to store, <strong>no registration is created at all</strong> and you can simply submit the form again. Nothing is half-created and you are never locked out of retrying.</p></blockquote><h3 id="_2-add-or-replace-a-document-after-signing-in" tabindex="-1">2. Add or replace a document after signing in <a class="header-anchor" href="#_2-add-or-replace-a-document-after-signing-in" aria-label="Permalink to &quot;2. Add or replace a document after signing in&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /auth/mitra/register/:id/upload/:docType</code></p><p><strong>Authentication:</strong> <strong>Bearer JWT (required).</strong> You must own the registration. Because every registration is bound to an account at submit time, an unauthenticated call here is always <code>403</code> — the first submission attaches its documents inline (<a href="#1-submit-a-registration-documents-included">§1</a>) instead.</p><p>Use this to:</p><ul><li>add the <strong>payment proof</strong> once you have the bank details;</li><li><strong>replace</strong> a document an admin asked you to redo.</li></ul><p><code>docType ∈ { spk, ktp, partnership, payment-proof }</code>. Multipart form field <code>file</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/mitra/register/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/upload/payment-proof&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;file=@proof.jpg&quot;</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the updated registration with the document linked, in the <a href="#what-the-registration-object-contains">customer shape</a>.</p><p><strong>Errors:</strong> <code>403</code> if the registration belongs to another account (or you are not signed in). <code>400</code> if the registration is already <code>APPROVED</code>.</p><blockquote><p>If the registration already carries a valid <code>spkNumber</code>, the uploaded SPK&#39;s display filename is set to the number (e.g. <code>05.123_ADI_07_2026.pdf</code>).</p></blockquote><h3 id="_3-check-registration-status" tabindex="-1">3. Check registration status <a class="header-anchor" href="#_3-check-registration-status" aria-label="Permalink to &quot;3. Check registration status&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /auth/mitra/application/status</code></p><p><strong>Authentication:</strong> Bearer JWT (the applicant&#39;s account).</p><p><strong>Response:</strong> <code>200 OK</code> — your latest registration, in the <a href="#what-the-registration-object-contains">customer shape</a>. If you were rejected and re-applied, this is the <strong>newest</strong> application.</p><hr><h2 id="what-the-registration-object-contains" tabindex="-1">What the registration object contains <a class="header-anchor" href="#what-the-registration-object-contains" aria-label="Permalink to &quot;What the registration object contains&quot;">​</a></h2><p><code>register</code>, <code>upload</code> and <code>application/status</code> all return the same <strong>customer shape</strong>:</p><table tabindex="0"><thead><tr><th>Returned</th><th></th></tr></thead><tbody><tr><td><code>id</code>, <code>status</code>, <code>tier</code>, <code>applicantType</code></td><td></td></tr><tr><td><code>registrationNumber</code>, <code>registrationSeq</code></td><td><code>null</code> until approved</td></tr><tr><td><code>applicantName</code>, <code>applicantEmail</code>, <code>applicantPhone</code></td><td>your own data</td></tr><tr><td><code>companyName</code>, <code>companyAddress</code></td><td><code>null</code> ⇒ you are an individual partner</td></tr><tr><td><code>spkNumber</code></td><td></td></tr><tr><td><code>rejectionReason</code></td><td>why you were rejected — <code>null</code> otherwise</td></tr><tr><td><code>organizationId</code></td><td><code>null</code> ⇒ no organization</td></tr><tr><td><code>spkDocument</code>, <code>ktpDocument</code>, <code>partnershipDocument</code>, <code>paymentProofDocument</code></td><td>each <code>{ id, filename, uploadedAt }</code> or <code>null</code></td></tr><tr><td><code>submittedAt</code>, <code>reviewedAt</code>, <code>createdAt</code>, <code>updatedAt</code></td><td></td></tr></tbody></table><p>The reviewer&#39;s internal fields — admin notes, the audit log, the reviewing admin, and the request metadata captured at submission — are <strong>never</strong> returned on these endpoints.</p><p>Fetch a document with <code>GET /storage/{id}/download</code> using the <code>id</code> from a document slot. You own your own uploads; they cannot be deleted once submitted (they are review evidence — ask an admin).</p><hr><h2 id="while-your-application-is-under-review" tabindex="-1">While your application is under review <a class="header-anchor" href="#while-your-application-is-under-review" aria-label="Permalink to &quot;While your application is under review&quot;">​</a></h2><p>You can <strong>log in from the moment you submit</strong> — with the email you registered with, by OTP or Google — and you stay logged in through a rejection, so you can read why and re-apply.</p><p>On the <strong>mitra portal</strong>, an application that is not yet approved gets you your own application and nothing else:</p><table tabindex="0"><thead><tr><th>You can</th><th>You cannot (until approved)</th></tr></thead><tbody><tr><td><code>GET /auth/profile</code></td><td>Book (<code>/custom-booking</code>, <code>/custom-ota/book/calculate</code>)</td></tr><tr><td><code>GET /auth/mitra/application/status</code></td><td><code>GET /wallet</code> — <strong>403</strong></td></tr><tr><td>Re-submit: <code>POST /auth/mitra/register</code> (documents inline)</td><td><code>GET /invoice</code></td></tr><tr><td>Add / replace a document: <code>POST /auth/mitra/register/:id/upload/:docType</code></td><td></td></tr><tr><td><code>GET /storage/{id}/download</code> — your own documents</td><td></td></tr><tr><td>Log out</td><td></td></tr></tbody></table><p>Everything else on the mitra portal returns <strong><code>403</code></strong>.</p><p>Two things that surprise people, both deliberate:</p><ul><li><strong>Public search still works.</strong> <code>POST /custom-ota/search</code> is a guest surface, so you get the same public result (and the same public tier prices) a logged-out visitor gets. Logging in does not unlock partner pricing — approval does.</li><li><strong>On the main site nothing changes.</strong> There you are an ordinary customer, with a working wallet, for as long as your application is pending.</li></ul><p><code>GET /auth/profile</code> tells the frontend which of these you are, on the mitra portal only:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;promoAccessLevel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;APPLICANT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>APPLICANT</code> ⇒ your application is in flight. <code>PARTNER</code> ⇒ you are approved and the full portal is open. <code>DENIED</code> ⇒ this account has no access to the mitra portal.</p><p>The moment an admin approves you, your <strong>existing</strong> session becomes a partner session — no re-login.</p><h3 id="if-you-are-rejected" tabindex="-1">If you are rejected <a class="header-anchor" href="#if-you-are-rejected" aria-label="Permalink to &quot;If you are rejected&quot;">​</a></h3><p>You keep your login. Read <code>rejectionReason</code>, then <strong>submit a new registration</strong> (<code>POST /auth/mitra/register</code> again, with your documents attached as before) — you get a brand-new registration <code>id</code> carrying them. <code>application/status</code> then shows the new application. Your old rejected one stays on file.</p><hr><h2 id="post-approval" tabindex="-1">Post-Approval <a class="header-anchor" href="#post-approval" aria-label="Permalink to &quot;Post-Approval&quot;">​</a></h2><p>Both kinds of partner receive:</p><ul><li>a per-tier <strong>registration number</strong> (<code>MS.001</code> … <code>MS.999</code> … <code>MS.1000</code>, likewise <code>MG.</code>) — drawn from one shared per-tier counter, so organization and individual partners are numbered in the same sequence;</li><li>the tier&#39;s pricing access (Gold ⇒ special + promo; Silver ⇒ promo);</li><li>an approval email.</li></ul><p>What differs:</p><table tabindex="0"><thead><tr><th></th><th>Organization partner</th><th>Individual partner</th></tr></thead><tbody><tr><td>Organization</td><td>created</td><td><strong>none</strong></td></tr><tr><td>Organization wallet</td><td>created (SAR, balance <code>0</code>)</td><td><strong>none</strong></td></tr><tr><td>Account role</td><td>promoted to <code>B2B</code></td><td>stays <code>B2C</code></td></tr><tr><td>Where the tier lives</td><td>on the organization</td><td>on <strong>your account</strong></td></tr><tr><td>Personal SAR wallet</td><td>yes (created at registration)</td><td>yes (created at registration)</td></tr><tr><td>Approval email</td><td>shows an organization code</td><td>omits the organization-code row</td></tr></tbody></table><p>Your personal SAR wallet is created when you <strong>register</strong>, not at approval. The wallet endpoints work from submission onward <strong>on the main site</strong> — but they are <code>403</code> on the mitra portal until you are approved (see <a href="#while-your-application-is-under-review">While your application is under review</a>).</p><blockquote><p><strong>A Gold individual partner still owes the 50,000 SAR deposit.</strong> The deposit is keyed on the tier, not on whether you have a company. It is verified manually by an admin off-system and is <strong>not</strong> credited to any wallet balance.</p></blockquote><blockquote><p><strong>One approved registration per account, ever.</strong> After approval you cannot submit another registration (<code>409</code>) — including to change tier. Contact an admin instead.</p></blockquote><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/register-login/">Registration &amp; Login</a></li><li><a href="/ahlaan-train-docs/customer/b2b-registration/">B2B Registration Guide</a></li></ul>`,88)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
